      var v=String(obj[key]||'');
      if(/^data:image\//i.test(v))jobs.push(hudDiyAssetStoreBlob(hudDataUrlBlob(v)).then(function(ref){obj[key]=ref;changed=true;}));
      else if(v.indexOf(HUD_DIY_SCHEME)===0)hudDiyAssetResolve(v);
