    try{
      await Promise.all(jobs);
      if(changed){diySave({skipAssetMigration:true});hudDiagEvent('DIY','内联图片（DataURL/blob）已迁入 IndexedDB');}
      return changed;
    }catch(e){hudDiagError('DIY asset migrate',e);return false;}
