    var cmdUpd='/findentry file="'+book2+'" field=comment "'+title+'" | /setentryfield file="'+book2+'" uid={{pipe}} field=content '+one;
    sendMessage(cmdUpd);
    if(!silent)diyMsg('已保存编辑，并已更新世界书「'+book+'」中对应条目内容');
    return;
  }
  var dis='';
