    var l=rawL, t=rawT;
    var maxL=Math.max(0,vp.w-size), maxT=Math.max(0,vp.h-size);
    if(isNaN(l)||l<0||l>maxL)l=vp.w-size-edge;
    if(isNaN(t)||t<0||t>maxT)t=vp.h-140-size;
